package com.gameaggregator.gamemediaservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.gamemediaservice.application.MediaService;import com.gameaggregator.gamemediaservice.domain.GameMedia;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/game-media") public class MediaController{final MediaService s;public MediaController(MediaService s){this.s=s;}@PostMapping("/presigned-upload")ApiResponse<MediaDtos.UploadUrl> presign(@Valid @RequestBody MediaDtos.Presign r){return ApiResponse.success(s.presign(r));}@PostMapping("/complete")ApiResponse<GameMedia> complete(@Valid @RequestBody MediaDtos.Complete r){return ApiResponse.success(s.complete(r));}@GetMapping("/games/{gameId}")ApiResponse<List<GameMedia>> list(@PathVariable UUID gameId){return ApiResponse.success(s.list(gameId));}}